// Why this file exists: the desktop's own applyTheme (themes/context.tsx:
// 314-383) paints a strict superset of the tokens our port paints. Until the
// port carried them, applying a Chroma scene left --dt-primary-solid and
// --ui-success at the PREVIOUS skin's values — a defect independent of the
// accent-picker plugin that motivated it.
//
// The goldens below were generated by compiling the HOST's own
// apps/desktop/src/themes/color.ts to plain JS with esbuild and running the
// host's real harmonize / hexToOklch / oklchToHex on these inputs (2026-10-29,
// pinned desktop tree). Numeric-parity doctrine: our port must reproduce the
// host bit for bit, so a gate compares against values the HOST produced, not
// against values our port produced.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { loadPlugin } from './helpers/load-plugin.mjs'

const GOLDEN_HARMONIZE = {
  '#0053fd': '#00b5aa',
  '#e5484d': '#80af2a',
  '#7c5cbf': '#00b3b5',
  '#2ea043': '#2cb879',
  '#f5a623': '#67b356',
  '#6d6d6d': '#5cb55e'
}

const GOLDEN_ROUNDTRIP = {
  '#0053fd': '#0053fd',
  '#fcfcfc': '#fcfcfc',
  '#161616': '#161616',
  '#10b981': '#10b981'
}

// Alabaster's dark-mode midground is #7CA1FA; the host's own code answers
// harmonize(SUCCESS_SEED, '#7CA1FA', 0.25) with this. A probe against the
// compiled host tree produced it on 2026-10-29 (see header note).
const SUCCESS_GOLDEN = '#00b5ac'

test('the ported OKLCH maths reproduces the host bit for bit', async () => {
  const { context } = await loadPlugin()
  const { harmonize, hexToOklch, oklchToHex } = context.testHelpers
  assert.equal(typeof harmonize, 'function', 'harmonize must exist')
  assert.equal(typeof hexToOklch, 'function')
  assert.equal(typeof oklchToHex, 'function')

  for (const [accent, expected] of Object.entries(GOLDEN_HARMONIZE)) {
    assert.equal(harmonize('#10b981', accent, 0.25), expected, `harmonize ${accent}`)
  }

  for (const [hex, expected] of Object.entries(GOLDEN_ROUNDTRIP)) {
    const oklch = hexToOklch(hex)
    assert.equal(oklchToHex(oklch), expected, `oklch roundtrip ${hex}`)
  }
})

// WCAG luminance, usable both as the acceptance metric and against goldens the
// port itself is not allowed to influence (it is exactly the formula the host
// compile used to verify --dt-primary-solid clears AA on its foreground).
function wcagLuminance(hex) {
  const v = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map(c => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4))
  return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2]
}
function wcagRatio(a, b) {
  const la = wcagLuminance(a)
  const lb = wcagLuminance(b)
  const [hi, lo] = la >= lb ? [la, lb] : [lb, la]
  return (hi + 0.05) / (lo + 0.05)
}

test('a scene application paints the loud fill and success tokens the host paints', async () => {
  const { context } = await loadPlugin()
  const { applyDesktopTheme, sceneToDesktopTheme } = context.testHelpers
  assert.equal(typeof applyDesktopTheme, 'function', 'the port must be reachable')

  const scene = context.testHelpers.SKINS.find(s => s.name === 'alabaster')
  assert.ok(scene, 'fixture: alabaster must ship')
  const theme = sceneToDesktopTheme(scene)

  const tokens = {}
  // The shipped build reads document.documentElement.style.setProperty; the
  // harness hands us the same document element, so swap the capture in before
  // the paint and read it back after.
  const root = context.document.documentElement
  const original = root.style.setProperty
  root.style.setProperty = (key, value) => { tokens[key] = value }

  try {
    applyDesktopTheme(theme, 'dark')
  } finally {
    root.style.setProperty = original
  }

  assert.equal(tokens['--dt-primary-solid-foreground'], '#fcfcfc',
    'the loud fill foreground is the host constant, byte-identical (context.tsx:279)')
  assert.ok(tokens['--dt-primary-solid'], 'a loud fill must carry a concrete hex')

  const solid = tokens['--dt-primary-solid']
  assert.ok(solid.startsWith('#') && solid.length === 7, `solid reads a 6-digit hex: ${solid}`)
  assert.ok(wcagRatio(solid, '#fcfcfc') >= 4.5,
    `the loud fill clears AA on its own foreground: ${wcagRatio(solid, '#fcfcfc').toFixed(2)}`)

  assert.equal(tokens['--ui-success'], SUCCESS_GOLDEN,
    '--ui-success is harmonize(SUCCESS_SEED, the scene midground, 0.25), matching the host byte for byte')

  // The two failure modes of a fallback-heavy port, both forbidden here.
  assert.notEqual(tokens['--ui-success'], '#10b981',
    'an identical seed means harmonize was skipped — the host never does that on a foreign accent')
  assert.equal(tokens['--dt-primary-solid'], solid,
    'the solid must be the deepened primary, not the raw palette primary')
})
